import { existsSync, readdirSync } from "node:fs";
import { dirname, join, relative, sep } from "node:path";
import ts from "typescript";
import { discoverChannels } from "../channels/discovery";

const header =
  "/** AUTO-GENERATED BY TAKO — DO NOT EDIT. Publish this file through your own package. */\n";
const sourceFile = /(?<!\.d)\.(?:ts|tsx|mts|js|mjs)$/;

function modulePath(from: string, to: string): string {
  const path = relative(from, to)
    .split(sep)
    .join("/")
    .replace(/(?:\.d)?\.ts$/, "");
  return path.startsWith(".") ? path : `./${path}`;
}

/** Resolve aliases and interfaces into a standalone declaration graph. No producer imports escape. */
class DeclarationGraph {
  readonly declarations: string[] = [];
  private readonly objects = new Map<ts.Type, string>();
  constructor(
    private readonly checker: ts.TypeChecker,
    private readonly location: ts.Node,
  ) {}

  print(type: ts.Type): string {
    const f = type.flags;
    if (f & (ts.TypeFlags.Any | ts.TypeFlags.Unknown)) return "unknown";
    if (f & ts.TypeFlags.Never) return "never";
    if (f & ts.TypeFlags.Undefined) return "undefined";
    if (f & ts.TypeFlags.Null) return "null";
    if (type.isStringLiteral()) return JSON.stringify(type.value);
    if (type.isNumberLiteral()) return String(type.value);
    if (f & ts.TypeFlags.BooleanLiteral) return this.checker.typeToString(type);
    if (f & ts.TypeFlags.String) return "string";
    if (f & ts.TypeFlags.Number) return "number";
    if (f & ts.TypeFlags.Boolean) return "boolean";
    if (f & ts.TypeFlags.Void) return "null";
    if (f & ts.TypeFlags.TemplateLiteral) {
      const template = type as ts.TemplateLiteralType;
      const escape = (value: string) =>
        value.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");
      return (
        "`" +
        template.texts
          .map(
            (part, i) =>
              escape(part) +
              (i < template.types.length ? "${" + this.print(template.types[i]!) + "}" : ""),
          )
          .join("") +
        "`"
      );
    }
    const prior = this.objects.get(type);
    if (prior) return prior;
    const name = `_NetworkType${this.objects.size + 1}`;
    this.objects.set(type, name);
    const value = this.compound(type);
    this.declarations.push(`type ${name} = ${value};`);
    return name;
  }

  private compound(type: ts.Type): string {
    if (type.isUnion()) return `(${type.types.map((t) => this.print(t)).join(" | ")})`;
    if (type.isIntersection()) return `(${type.types.map((t) => this.print(t)).join(" & ")})`;
    if (this.checker.isTupleType(type)) {
      const ref = type as ts.TypeReference;
      const target = ref.target as ts.TupleType;
      const items = this.checker.getTypeArguments(ref).map((item, i) => {
        const flag = target.elementFlags[i] ?? ts.ElementFlags.Required;
        const value = this.print(item);
        return flag & ts.ElementFlags.Rest
          ? `...(${value})[]`
          : flag & ts.ElementFlags.Optional
            ? `(${value})?`
            : value;
      });
      return `${target.readonly ? "readonly " : ""}[${items.join(", ")}]`;
    }
    if (this.checker.isArrayType(type)) {
      const array = type.getSymbol()?.getName() === "ReadonlyArray" ? "ReadonlyArray" : "Array";
      return `${array}<${this.print(this.checker.getTypeArguments(type as ts.TypeReference)[0]!)}>`;
    }
    if (
      !(type.flags & ts.TypeFlags.Object) ||
      type.getCallSignatures().length ||
      type.getConstructSignatures().length
    ) {
      throw new Error(
        `Network contracts require JSON data; unsupported type: ${this.checker.typeToString(type)}`,
      );
    }
    const properties = this.checker.getPropertiesOfType(type).map((property) => {
      if (property.getName().startsWith("__@"))
        throw new Error("Symbol properties cannot be exported in network contracts");
      const value = this.checker.getTypeOfSymbolAtLocation(
        property,
        property.valueDeclaration ?? this.location,
      );
      return `${JSON.stringify(property.getName())}${property.flags & ts.SymbolFlags.Optional ? "?" : ""}: ${this.print(value)};`;
    });
    for (const index of this.checker.getIndexInfosOfType(type)) {
      properties.push(`[key: ${this.print(index.keyType)}]: ${this.print(index.type)};`);
    }
    return `{ ${properties.join(" ")} }`;
  }

  printResult(type: ts.Type): string {
    if (type.flags & (ts.TypeFlags.Undefined | ts.TypeFlags.Void)) return "null";
    if (type.isUnion()) return `(${type.types.map((item) => this.printResult(item)).join(" | ")})`;
    return this.print(type);
  }
}

function exportType(checker: ts.TypeChecker, file: ts.SourceFile, name: string): ts.Type {
  const module = checker.getSymbolAtLocation(file);
  const symbol = module && checker.getExportsOfModule(module).find((s) => s.getName() === name);
  if (!symbol) throw new Error(`${file.fileName}: missing export ${name}`);
  const resolved = symbol.flags & ts.SymbolFlags.Alias ? checker.getAliasedSymbol(symbol) : symbol;
  return resolved.flags & ts.SymbolFlags.TypeAlias || resolved.flags & ts.SymbolFlags.Interface
    ? checker.getDeclaredTypeOfSymbol(resolved)
    : checker.getTypeOfSymbolAtLocation(resolved, resolved.valueDeclaration ?? file);
}

function propertyType(checker: ts.TypeChecker, type: ts.Type, name: string, at: ts.Node): ts.Type {
  const symbol = type.getProperty(name);
  if (!symbol) throw new Error(`${at.getSourceFile().fileName}: contract is missing ${name}`);
  return checker.getTypeOfSymbolAtLocation(symbol, symbol.valueDeclaration ?? at);
}

function contractName(name: string, kind: string): string {
  const parts = name.split(/[^a-zA-Z0-9]+/).filter(Boolean);
  const result = parts.map((part) => part[0]!.toUpperCase() + part.slice(1)).join("");
  return `${/^[0-9]/.test(result) ? "_" : ""}${result}${kind}`;
}

/** Both files are computed before the CLI writes either one. */
export async function generateNetworkTypes(
  root: string,
  declarationDir: string,
  app: string,
): Promise<{ declarations: string; contracts: string }> {
  if (!/^[a-z][a-z0-9-]*$/.test(app) || app.endsWith("-") || app.length > 63)
    throw new Error("Network contracts require a valid app name in tako.toml");
  const channels = await discoverChannels(join(root, "channels"));
  const workflowDir = join(root, "workflows");
  const workflows = existsSync(workflowDir)
    ? readdirSync(workflowDir, { withFileTypes: true })
        .filter(
          (entry) => entry.isFile() && sourceFile.test(entry.name) && !/^[._]/.test(entry.name),
        )
        .map((entry) => ({
          name: entry.name.replace(/\.[^.]+$/, ""),
          path: join(workflowDir, entry.name),
        }))
        .sort((a, b) => a.name.localeCompare(b.name))
    : [];
  const channelFiles = channels.map((channel) => {
    const file = readdirSync(join(root, "channels")).find(
      (name) => name.replace(/\.[^.]+$/, "") === channel.fileStem && sourceFile.test(name),
    );
    if (!file) throw new Error(`Channel source disappeared: ${channel.name}`);
    return { ...channel, path: join(root, "channels", file) };
  });
  const handlerDir = join(root, "network-handlers");
  const handlers = existsSync(handlerDir)
    ? readdirSync(handlerDir, { withFileTypes: true })
        .filter(
          (entry) => entry.isFile() && sourceFile.test(entry.name) && !/^[._]/.test(entry.name),
        )
        .map((entry) => ({
          name: entry.name.replace(/\.[^.]+$/, ""),
          path: join(handlerDir, entry.name),
        }))
        .sort((a, b) => a.name.localeCompare(b.name))
    : [];
  const externalFiles = [join(declarationDir, "tako.imports.ts")].filter(existsSync);
  const files = [...channelFiles, ...workflows, ...handlers]
    .map((entry) => entry.path)
    .concat(externalFiles);
  const configPath = ts.findConfigFile(root, ts.sys.fileExists);
  let options: ts.CompilerOptions = {
    target: ts.ScriptTarget.ESNext,
    module: ts.ModuleKind.ESNext,
    moduleResolution: ts.ModuleResolutionKind.Bundler,
    strict: true,
    allowJs: true,
    skipLibCheck: true,
    noEmit: true,
  };
  if (configPath) {
    const config = ts.readConfigFile(configPath, ts.sys.readFile);
    if (config.error)
      throw new Error(ts.flattenDiagnosticMessageText(config.error.messageText, "\n"));
    options = {
      ...options,
      ...ts.parseJsonConfigFileContent(config.config, ts.sys, dirname(configPath)).options,
      noEmit: true,
    };
  }
  let program = ts.createProgram(files, options);
  let checker = program.getTypeChecker();
  // Resolve calls between primitives against their source types, without reading
  // stale generated declarations. This also lets a handler forward an imported
  // workflow/handler result with its actual type on the first generation.
  const virtualPath = join(declarationDir, "__tako_network_generation.d.ts");
  const sourceRef = (path: string) =>
    `typeof import(${JSON.stringify(path.replace(/\.[^.]+$/, ""))}).default`;
  const maps = {
    workflow: new Map<string, string>(),
    channel: new Map<string, string>(),
    handler: new Map<string, string>(),
  };
  for (const [kind, entries] of [
    ["workflow", workflows],
    ["channel", channelFiles],
    ["handler", handlers],
  ] as const) {
    for (const entry of entries) {
      const address = `${app}.${entry.name}`;
      const source = sourceRef(entry.path);
      const value =
        kind === "channel"
          ? `{ kind: "channel"; address: ${JSON.stringify(address)}; params: NonNullable<_Handle<${source}>["__params"]>; messages: NonNullable<_Handle<${source}>["__messages"]> }`
          : `{ kind: ${JSON.stringify(kind)}; address: ${JSON.stringify(address)}; ${kind === "workflow" ? "payload" : "input"}: Parameters<_Handler<${source}>>[0]; result: _Output<Awaited<ReturnType<_Handler<${source}>>>> }`;
      maps[kind].set(address, value);
      maps[kind].set(entry.name, value);
    }
  }
  for (const path of externalFiles) {
    const file = program.getSourceFile(path)!;
    const module = checker.getSymbolAtLocation(file);
    if (!module) continue;
    for (const symbol of checker.getExportsOfModule(module)) {
      const type = exportType(checker, file, symbol.getName());
      const kind = propertyType(checker, type, "kind", file);
      const address = propertyType(checker, type, "address", file);
      if (
        kind.isStringLiteral() &&
        ["workflow", "channel", "handler"].includes(kind.value) &&
        address.isStringLiteral()
      ) {
        maps[kind.value as keyof typeof maps].set(
          address.value,
          `import(${JSON.stringify(path.replace(/\.ts$/, ""))}).${symbol.getName()}`,
        );
      }
    }
  }
  const virtual = `import "tako.sh";
type _Handler<T> = T extends { definition: { handler: infer H extends (...args: any[]) => any } } ? H : T extends { handler: infer H extends (...args: any[]) => any } ? H : T extends (...args: any[]) => any ? T : never;
type _Handle<T> = T extends (...args: any[]) => infer H ? H : T;
type _Output<T> = T extends void ? null : T;
declare module "tako.sh" { ${Object.entries(maps)
    .map(
      ([kind, entries]) =>
        `interface TakoNetwork${kind === "workflow" ? "Workflows" : kind === "handler" ? "Handlers" : "Channels"} { ${[...entries].map(([name, value]) => `${JSON.stringify(name)}: ${value};`).join("\n")} }`,
    )
    .join("\n")} }`;
  const host = ts.createCompilerHost(options);
  const getSourceFile = host.getSourceFile.bind(host);
  host.getSourceFile = (fileName, languageVersion, onError, shouldCreateNewSourceFile) =>
    fileName === virtualPath
      ? ts.createSourceFile(fileName, virtual, ts.ScriptTarget.Latest)
      : getSourceFile(fileName, languageVersion, onError, shouldCreateNewSourceFile);
  program = ts.createProgram([...files, virtualPath], options, host);
  checker = program.getTypeChecker();
  const exported: string[] = [];
  const graph = new DeclarationGraph(
    checker,
    program.getSourceFile(files[0] ?? "") ??
      ts.createSourceFile("contracts.ts", "", ts.ScriptTarget.Latest),
  );
  const localModule = "./tako.exports";
  const registries = {
    workflow: new Map<string, string>(),
    channel: new Map<string, string>(),
    handler: new Map<string, string>(),
  };
  const exportedNames = new Set<string>();
  for (const [kind, entries] of [
    ["workflow", workflows],
    ["channel", channelFiles],
    ["handler", handlers],
  ] as const) {
    for (const entry of entries) {
      if (!/^[A-Za-z0-9_:-]{1,255}$/.test(entry.name))
        throw new Error(`Invalid network primitive name: ${entry.name}`);
      const file = program.getSourceFile(entry.path);
      if (!file) throw new Error(`Missing TypeScript source: ${entry.path}`);
      const type = exportType(checker, file, "default");
      const name = contractName(
        entry.name,
        { workflow: "Workflow", channel: "Channel", handler: "Handler" }[kind],
      );
      if (exportedNames.has(name)) throw new Error(`Conflicting generated contract name: ${name}`);
      exportedNames.add(name);
      const address = `${app}.${entry.name}`;
      let fields: string;
      if (kind === "workflow" || kind === "handler") {
        const definition = type.getProperty("definition");
        const handle = definition ? checker.getTypeOfSymbolAtLocation(definition, file) : type;
        const handler = handle.getProperty("handler");
        const signature = (
          handler ? checker.getTypeOfSymbolAtLocation(handler, file) : handle
        ).getCallSignatures()[0];
        if (!signature) throw new Error(`${entry.path}: expected a ${kind} export`);
        const payload = signature.getParameters()[0];
        const result =
          checker.getAwaitedType(signature.getReturnType()) ?? signature.getReturnType();
        fields = `${kind === "workflow" ? "payload" : "input"}: ${payload ? graph.print(checker.getTypeOfSymbolAtLocation(payload, file)) : "unknown"}; result: ${graph.printResult(result)};`;
      } else {
        const handle = type.getCallSignatures()[0]?.getReturnType() ?? type;
        fields = ["params", "messages"]
          .map((key) => {
            const marker = propertyType(checker, handle, `__${key}`, file);
            return `${key}: ${graph.print(checker.getNonNullableType(marker))};`;
          })
          .join(" ");
      }
      exported.push(
        `export type ${name} = { readonly kind: ${JSON.stringify(kind)}; readonly address: ${JSON.stringify(address)}; ${fields} };`,
      );
      const reference = `import(${JSON.stringify(localModule)}).${name}`;
      registries[kind].set(entry.name, reference);
      registries[kind].set(address, reference);
    }
  }
  for (const path of externalFiles) {
    const file = program.getSourceFile(path)!;
    const diagnostics = [
      ...program.getSyntacticDiagnostics(file),
      ...program.getSemanticDiagnostics(file),
    ];
    if (diagnostics.length)
      throw new Error(
        ts.formatDiagnosticsWithColorAndContext(diagnostics, {
          getCurrentDirectory: () => root,
          getCanonicalFileName: (f) => f,
          getNewLine: () => "\n",
        }),
      );
    const module = checker.getSymbolAtLocation(file);
    if (!module) continue;
    for (const symbol of checker.getExportsOfModule(module)) {
      const name = symbol.getName();
      if (name === "default")
        throw new Error(`${path}: use named type exports for network contracts`);
      const type = exportType(checker, file, name);
      const declaredKind = propertyType(checker, type, "kind", file);
      const address = propertyType(checker, type, "address", file);
      if (
        !declaredKind.isStringLiteral() ||
        !["workflow", "channel", "handler"].includes(declaredKind.value) ||
        !address.isStringLiteral() ||
        !/^[a-z][a-z0-9-]*\.[A-Za-z0-9_:-]+$/.test(address.value)
      ) {
        throw new Error(
          `${path}: ${name} must be a workflow, channel, or handler contract with one qualified string address`,
        );
      }
      const kind = declaredKind.value as keyof typeof registries;
      for (const key of kind === "workflow"
        ? ["payload", "result"]
        : kind === "handler"
          ? ["input", "result"]
          : ["params", "messages"])
        propertyType(checker, type, key, file);
      if (registries[kind].has(address.value))
        throw new Error(`${path}: duplicate network address ${address.value}`);
      registries[kind].set(
        address.value,
        `import(${JSON.stringify(modulePath(declarationDir, path))}).${name}`,
      );
    }
  }
  const declarations = Object.entries(registries)
    .map(
      ([kind, registry]) =>
        `export interface TakoNetwork${kind === "workflow" ? "Workflows" : kind === "handler" ? "Handlers" : "Channels"} {\n${[
          ...registry,
        ]
          .sort(([a], [b]) => a.localeCompare(b))
          .map(([address, type]) => `  ${JSON.stringify(address)}: ${type};`)
          .join("\n")}\n}`,
    )
    .join("\n\n");
  return {
    declarations,
    contracts: `${header}\n${graph.declarations.join("\n")}\n\n${exported.join("\n\n")}\n${exported.length ? "" : "export {};\n"}`,
  };
}
